CREATE TABLE IF NOT EXISTS guild_workspace_lease_mutations (
    Id TEXT NOT NULL PRIMARY KEY CHECK(typeof(Id)='text' AND Id=upper(Id) AND length(Id)=36 AND substr(Id,9,1)='-' AND substr(Id,14,1)='-' AND substr(Id,19,1)='-' AND substr(Id,24,1)='-' AND length(replace(Id,'-',''))=32 AND replace(Id,'-','') NOT GLOB '*[^0-9A-F]*' AND Id<>'00000000-0000-0000-0000-000000000000'),
    PrincipalId TEXT NOT NULL CHECK(typeof(PrincipalId)='text' AND PrincipalId=upper(PrincipalId) AND length(PrincipalId)=36 AND substr(PrincipalId,9,1)='-' AND substr(PrincipalId,14,1)='-' AND substr(PrincipalId,19,1)='-' AND substr(PrincipalId,24,1)='-' AND length(replace(PrincipalId,'-',''))=32 AND replace(PrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND PrincipalId<>'00000000-0000-0000-0000-000000000000'),
    QuestId TEXT NULL CHECK(QuestId IS NULL OR (typeof(QuestId)='text' AND QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000')),
    IdempotencyKey TEXT NOT NULL CHECK(typeof(IdempotencyKey)='text' AND IdempotencyKey=upper(IdempotencyKey) AND length(IdempotencyKey)=36 AND substr(IdempotencyKey,9,1)='-' AND substr(IdempotencyKey,14,1)='-' AND substr(IdempotencyKey,19,1)='-' AND substr(IdempotencyKey,24,1)='-' AND length(replace(IdempotencyKey,'-',''))=32 AND replace(IdempotencyKey,'-','') NOT GLOB '*[^0-9A-F]*' AND IdempotencyKey<>'00000000-0000-0000-0000-000000000000'),
    RequestDigest TEXT NOT NULL CHECK(typeof(RequestDigest)='text' AND length(RequestDigest)=64 AND RequestDigest NOT GLOB '*[^0-9A-F]*'),
    ActionCode INTEGER NOT NULL CHECK(typeof(ActionCode)='integer' AND ActionCode IN(1,2,3)),
    LeaseId TEXT NOT NULL REFERENCES guild_workspace_leases(Id) ON DELETE RESTRICT CHECK(typeof(LeaseId)='text' AND LeaseId=upper(LeaseId) AND length(LeaseId)=36 AND substr(LeaseId,9,1)='-' AND substr(LeaseId,14,1)='-' AND substr(LeaseId,19,1)='-' AND substr(LeaseId,24,1)='-' AND length(replace(LeaseId,'-',''))=32 AND replace(LeaseId,'-','') NOT GLOB '*[^0-9A-F]*' AND LeaseId<>'00000000-0000-0000-0000-000000000000'),
    AcceptedAtUtc TEXT NOT NULL CHECK(typeof(AcceptedAtUtc)='text' AND length(AcceptedAtUtc)=28),
    SnapshotJson TEXT NOT NULL CHECK(typeof(SnapshotJson)='text' AND length(CAST(SnapshotJson AS BLOB)) BETWEEN 1 AND 4096)
);
